-- Use with existing MaiTroll user_profiles(id, display_name, username, troll_coins).
-- Do NOT install the anonymous wallet migration included with the original Bolt ZIP.
create table if not exists public.mai_run_lobbies(id uuid primary key default gen_random_uuid(),host_id uuid not null references auth.users(id),guest_id uuid references auth.users(id),difficulty text not null check(difficulty in ('easy','normal','brutal','nightmare')),status text not null default 'waiting' check(status in ('waiting','playing','finished','cancelled')),seed integer not null default floor(random()*2147483647)::int,created_at timestamptz not null default now(),started_at timestamptz,check(host_id is distinct from guest_id));
create table if not exists public.mai_run_results(id uuid primary key default gen_random_uuid(),player_id uuid not null references auth.users(id),lobby_id uuid references public.mai_run_lobbies(id),difficulty text not null check(difficulty in ('easy','normal','brutal','nightmare')),gender text not null check(gender in ('male','female')),entry_fee int not null,status text not null default 'active' check(status in ('active','finished')),score int not null default 0,levels_cleared int not null default 0,letters_collected int not null default 0,coins_collected int not null default 0,created_at timestamptz not null default now(),finished_at timestamptz);
create index if not exists mai_run_lobbies_status_idx on public.mai_run_lobbies(status,created_at desc);
create index if not exists mai_run_results_player_idx on public.mai_run_results(player_id,created_at desc);
alter table public.mai_run_lobbies enable row level security;
alter table public.mai_run_results enable row level security;
revoke all on public.mai_run_lobbies,public.mai_run_results from anon,authenticated;
grant select on public.mai_run_lobbies,public.mai_run_results to authenticated;
create policy "Read game lobbies" on public.mai_run_lobbies for select to authenticated using(true);
create policy "Read own runs" on public.mai_run_results for select to authenticated using(player_id=(select auth.uid()));
create or replace function public.mai_run_fee(d text) returns int language sql immutable set search_path=public as $$ select case d when 'easy' then 10 when 'normal' then 20 when 'brutal' then 35 when 'nightmare' then 50 else null end $$;
create or replace function public.mai_run_start_solo(p_gender text,p_difficulty text) returns uuid language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid();fee int:=public.mai_run_fee(p_difficulty);rid uuid; begin
if uid is null then raise exception 'Sign in required';end if;
if fee is null or p_gender not in('male','female') then raise exception 'Invalid settings';end if;
update public.user_profiles set troll_coins=troll_coins-fee where id=uid and troll_coins>=fee;
if not found then raise exception 'Not enough Troll Coins';end if;
insert into public.mai_run_results(player_id,difficulty,gender,entry_fee) values(uid,p_difficulty,p_gender,fee) returning id into rid;return rid;end $$;
create or replace function public.mai_run_create_lobby(p_difficulty text) returns uuid language plpgsql security definer set search_path=public as $$ declare uid uuid:=auth.uid();rid uuid;begin if uid is null then raise exception 'Sign in required';end if;if public.mai_run_fee(p_difficulty) is null then raise exception 'Invalid difficulty';end if;insert into public.mai_run_lobbies(host_id,difficulty) values(uid,p_difficulty) returning id into rid;return rid;end $$;
create or replace function public.mai_run_join_lobby(p_lobby uuid) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;update public.mai_run_lobbies set guest_id=auth.uid() where id=p_lobby and status='waiting' and guest_id is null and host_id<>auth.uid();if not found then raise exception 'Lobby unavailable';end if;end $$;
create or replace function public.mai_run_begin_match(p_lobby uuid) returns uuid language plpgsql security definer set search_path=public as $$ declare lobby public.mai_run_lobbies%rowtype;fee int;begin
if auth.uid() is null then raise exception 'Sign in required';end if;
select * into lobby from public.mai_run_lobbies where id=p_lobby for update;
if not found or lobby.host_id<>auth.uid() or lobby.guest_id is null or lobby.status<>'waiting' then raise exception 'Lobby not ready';end if;
fee:=public.mai_run_fee(lobby.difficulty);
perform 1 from public.user_profiles where id in(lobby.host_id,lobby.guest_id) order by id for update;
if (select count(*) from public.user_profiles where id in(lobby.host_id,lobby.guest_id) and troll_coins>=fee)<>2 then raise exception 'Both players need enough Troll Coins';end if;
update public.user_profiles set troll_coins=troll_coins-fee where id in(lobby.host_id,lobby.guest_id);
insert into public.mai_run_results(player_id,lobby_id,difficulty,gender,entry_fee) select v.pid,lobby.id,lobby.difficulty,'female',fee from (values(lobby.host_id),(lobby.guest_id)) v(pid);
update public.mai_run_lobbies set status='playing',started_at=now() where id=p_lobby;
return p_lobby;end $$;
create or replace function public.mai_run_cancel_lobby(p_lobby uuid) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;update public.mai_run_lobbies set status='cancelled' where id=p_lobby and status='waiting' and host_id=auth.uid();if not found then update public.mai_run_lobbies set guest_id=null where id=p_lobby and status='waiting' and guest_id=auth.uid();end if;end $$;
create or replace function public.mai_run_finish(p_run uuid,p_score int,p_levels int,p_letters int,p_collected int) returns void language plpgsql security definer set search_path=public as $$ begin if auth.uid() is null then raise exception 'Sign in required';end if;update public.mai_run_results set status='finished',score=least(greatest(coalesce(p_score,0),0),10000000),levels_cleared=least(greatest(coalesce(p_levels,0),0),8),letters_collected=least(greatest(coalesce(p_letters,0),0),8),coins_collected=least(greatest(coalesce(p_collected,0),0),5000),finished_at=now() where id=p_run and player_id=auth.uid() and status='active';if not found then raise exception 'Run already finished or unavailable';end if;
-- Client-reported scores are not verifiable: NEVER credit real Troll Coins here.
end $$;
create or replace function public.mai_run_leaderboard(p_limit int default 20) returns table(player_name text,gender text,difficulty text,score int,levels_cleared int,letters_collected int,finished_at timestamptz) language sql stable security definer set search_path=public as $$ select coalesce(p.display_name,p.username,'Troll')::text,r.gender,r.difficulty,r.score,r.levels_cleared,r.letters_collected,r.finished_at from public.mai_run_results r join public.user_profiles p on p.id=r.player_id where r.status='finished' order by r.score desc,r.finished_at asc limit least(greatest(coalesce(p_limit,20),1),100) $$;
create or replace function public.mai_run_match_results(p_lobby uuid) returns table(player_id uuid,levels_cleared int,score int,status text) language sql stable security definer set search_path=public as $$ select r.player_id,r.levels_cleared,r.score,r.status from public.mai_run_results r join public.mai_run_lobbies l on l.id=r.lobby_id where l.id=p_lobby and auth.uid() in(l.host_id,l.guest_id) $$;
revoke execute on function public.mai_run_fee(text),public.mai_run_start_solo(text,text),public.mai_run_create_lobby(text),public.mai_run_join_lobby(uuid),public.mai_run_begin_match(uuid),public.mai_run_cancel_lobby(uuid),public.mai_run_finish(uuid,int,int,int,int),public.mai_run_leaderboard(int),public.mai_run_match_results(uuid) from public;
grant execute on function public.mai_run_start_solo(text,text),public.mai_run_create_lobby(text),public.mai_run_join_lobby(uuid),public.mai_run_begin_match(uuid),public.mai_run_cancel_lobby(uuid),public.mai_run_finish(uuid,int,int,int,int),public.mai_run_leaderboard(int),public.mai_run_match_results(uuid) to authenticated;
